299: copy_info(fido_dev_info_t *di, HDEVINFO devinfo, DWORD idx,
300:     SP_DEVICE_INTERFACE_DATA *ifdata)
301: {
302: 	HANDLE	dev = INVALID_HANDLE_VALUE;
