83: static int
84: webauthn_load(void)
85: {
86: 	DWORD n = 1;
87: 
88: 	if (webauthn_loaded || webauthn_handle != NULL) {
89: 		fido_log_debug("%s: already loaded", __func__);
90: 		return -1;
91: 	}
92: 	if ((webauthn_handle = LoadLibraryEx(TEXT("webauthn.dll"), NULL,
93: 	    LOAD_LIBRARY_SEARCH_SYSTEM32)) == NULL) {
94: 		fido_log_debug("%s: LoadLibrary", __func__);
95: 		return -1;
96: 	}
97: 
98: 	if ((webauthn_get_api_version =
99: 	    (webauthn_get_api_version_t *)GetProcAddress(webauthn_handle,
100: 	    "WebAuthNGetApiVersionNumber")) == NULL) {
101: 		fido_log_debug("%s: WebAuthNGetApiVersionNumber", __func__);
102: 		/* WebAuthNGetApiVersionNumber might not exist */
103: 	}
104: 	if (webauthn_get_api_version != NULL &&
105: 	    (n = webauthn_get_api_version()) < 1) {
106: 		fido_log_debug("%s: unsupported api %lu", __func__, (u_long)n);
107: 		goto fail;
108: 	}
109: 	fido_log_debug("%s: api version %lu", __func__, (u_long)n);
110: 	if ((webauthn_strerr =
111: 	    (webauthn_strerr_t *)GetProcAddress(webauthn_handle,
112: 	    "WebAuthNGetErrorName")) == NULL) {
113: 		fido_log_debug("%s: WebAuthNGetErrorName", __func__);
114: 		goto fail;
115: 	}
116: 	if ((webauthn_get_assert =
117: 	    (webauthn_get_assert_t *)GetProcAddress(webauthn_handle,
118: 	    "WebAuthNAuthenticatorGetAssertion")) == NULL) {
119: 		fido_log_debug("%s: WebAuthNAuthenticatorGetAssertion",
120: 		    __func__);
121: 		goto fail;
122: 	}
123: 	if ((webauthn_make_cred =
124: 	    (webauthn_make_cred_t *)GetProcAddress(webauthn_handle,
125: 	    "WebAuthNAuthenticatorMakeCredential")) == NULL) {
126: 		fido_log_debug("%s: WebAuthNAuthenticatorMakeCredential",
127: 		    __func__);
128: 		goto fail;
129: 	}
130: 	if ((webauthn_free_assert =
131: 	    (webauthn_free_assert_t *)GetProcAddress(webauthn_handle,
132: 	    "WebAuthNFreeAssertion")) == NULL) {
133: 		fido_log_debug("%s: WebAuthNFreeAssertion", __func__);
134: 		goto fail;
135: 	}
136: 	if ((webauthn_free_attest =
137: 	    (webauthn_free_attest_t *)GetProcAddress(webauthn_handle,
138: 	    "WebAuthNFreeCredentialAttestation")) == NULL) {
139: 		fido_log_debug("%s: WebAuthNFreeCredentialAttestation",
140: 		    __func__);
141: 		goto fail;
142: 	}
143: 
144: 	webauthn_loaded = true;
145: 
146: 	return 0;
147: fail:
148: 	fido_log_debug("%s: GetProcAddress", __func__);
149: 	webauthn_get_api_version = NULL;
150: 	webauthn_strerr = NULL;
151: 	webauthn_get_assert = NULL;
152: 	webauthn_make_cred = NULL;
153: 	webauthn_free_assert = NULL;
154: 	webauthn_free_attest = NULL;
155: 	FreeLibrary(webauthn_handle);
156: 	webauthn_handle = NULL;
157: 
158: 	return -1;
159: }
