161: static wchar_t *
162: to_utf16(const char *utf8)
163: {
164: 	int nch;
165: 	wchar_t *utf16;
166: 
167: 	if (utf8 == NULL) {
168: 		fido_log_debug("%s: NULL", __func__);
169: 		return NULL;
170: 	}
171: 	if ((nch = MultiByteToWideChar(CP_UTF8, 0, utf8, -1, NULL, 0)) < 1 ||
172: 	    (size_t)nch > MAXCHARS) {
173: 		fido_log_debug("%s: MultiByteToWideChar %d", __func__, nch);
174: 		return NULL;
175: 	}
176: 	if ((utf16 = calloc((size_t)nch, sizeof(*utf16))) == NULL) {
177: 		fido_log_debug("%s: calloc", __func__);
178: 		return NULL;
179: 	}
180: 	if (MultiByteToWideChar(CP_UTF8, 0, utf8, -1, utf16, nch) != nch) {
181: 		fido_log_debug("%s: MultiByteToWideChar", __func__);
182: 		free(utf16);
183: 		return NULL;
184: 	}
185: 
186: 	return utf16;
187: }
