387: static WEBAUTHN_HMAC_SECRET_SALT *
388: pack_hmac_salt(const fido_blob_t *in)
389: {
390: 	WEBAUTHN_HMAC_SECRET_SALT *s;
391: 
392: 	if (in->ptr == NULL ||
393: 	    (in->len != WEBAUTHN_CTAP_ONE_HMAC_SECRET_LENGTH &&
394: 	     in->len != 2 * WEBAUTHN_CTAP_ONE_HMAC_SECRET_LENGTH)) {
395: 		fido_log_debug("%s: salt %p/%zu", __func__,
396: 		    (const void *)in->ptr, in->len);
397: 		return NULL;
398: 	}
399: 	if ((s = calloc(1, sizeof(*s))) == NULL) {
400: 		fido_log_debug("%s: calloc", __func__);
401: 		return NULL;
402: 	}
403: 	if (in->len == WEBAUTHN_CTAP_ONE_HMAC_SECRET_LENGTH) {
404: 		s->cbFirst = (DWORD)in->len;
405: 		s->pbFirst = in->ptr;
406: 	} else { /* 2 * WEBAUTHN_CTAP_ONE_HMAC_SECRET_LENGTH */
407: 		s->cbFirst = (DWORD)in->len / 2;
408: 		s->pbFirst = in->ptr;
409: 		s->cbSecond = (DWORD)in->len / 2;
410: 		s->pbSecond = in->ptr + in->len / 2;
411: 	}
412: 
413: 	return s;
414: }
