416: static int
417: pack_cred_ext(WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS *opt,
418:     const fido_cred_extin_t *in)
419: {
420: 	WEBAUTHN_EXTENSIONS *exts = &opt->Extensions;
421: 	WEBAUTHN_EXTENSION *e;
422: 	WEBAUTHN_CRED_PROTECT_EXTENSION_IN *p;
423: 	WEBAUTHN_HMAC_SECRET_SALT *s;
424: 	BOOL *b;
425: 	size_t n = 0, i = 0;
426: 
427: 	if (in->attr.mask == 0) {
428: 		return 0; /* nothing to do */
429: 	}
430: 	if (in->attr.mask & ~(FIDO_EXT_HMAC_SECRET | FIDO_EXT_CRED_PROTECT |
431: 	    FIDO_EXT_HMAC_SECRET_MC)) {
432: 		fido_log_debug("%s: mask 0x%x", __func__, in->attr.mask);
433: 		return -1;
434: 	}
435: 	if (in->attr.mask & FIDO_EXT_HMAC_SECRET)
436: 		n++;
437: 	if (in->attr.mask & FIDO_EXT_CRED_PROTECT)
438: 		n++;
439: 	if ((exts->pExtensions = calloc(n, sizeof(*e))) == NULL) {
440: 		fido_log_debug("%s: calloc", __func__);
441: 		return -1;
442: 	}
443: 	exts->cExtensions = (DWORD)n;
444: 	if (in->attr.mask & FIDO_EXT_HMAC_SECRET) {
445: 		/*
446: 		 * NOTE: webauthn.dll ignores requests to enable hmac-secret
447: 		 * unless a discoverable credential is also requested.
448: 		 */
449: 		if ((b = calloc(1, sizeof(*b))) == NULL) {
450: 			fido_log_debug("%s: calloc", __func__);
451: 			return -1;
452: 		}
453: 		*b = true;
454: 		e = &exts->pExtensions[i];
455: 		e->pwszExtensionIdentifier =
456: 		    WEBAUTHN_EXTENSIONS_IDENTIFIER_HMAC_SECRET;
457: 		e->pvExtension = b;
458: 		e->cbExtension = sizeof(*b);
459: 		i++;
460: 	}
461: 	if (in->attr.mask & FIDO_EXT_CRED_PROTECT) {
462: 		if ((p = calloc(1, sizeof(*p))) == NULL) {
463: 			fido_log_debug("%s: calloc", __func__);
464: 			return -1;
465: 		}
466: 		p->dwCredProtect = (DWORD)in->attr.prot;
467: 		p->bRequireCredProtect = true;
468: 		e = &exts->pExtensions[i];
469: 		e->pwszExtensionIdentifier =
470: 		    WEBAUTHN_EXTENSIONS_IDENTIFIER_CRED_PROTECT;
471: 		e->pvExtension = p;
472: 		e->cbExtension = sizeof(*p);
473: 		i++;
474: 	}
475: 	if (in->attr.mask & FIDO_EXT_HMAC_SECRET_MC) {
476: 		if ((s = pack_hmac_salt(&in->hmac_salt)) == NULL) {
477: 			fido_log_debug("%s: pack_hmac_salt", __func__);
478: 			return -1;
479: 		}
480: 		opt->pPRFGlobalEval = s;
481: 		opt->dwFlags |= WEBAUTHN_AUTHENTICATOR_HMAC_SECRET_VALUES_FLAG;
482: 		opt->dwVersion = WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS_VERSION_8;
483: 	}
484: 
485: 	return 0;
486: }
