488: static int
489: pack_assert_ext(WEBAUTHN_AUTHENTICATOR_GET_ASSERTION_OPTIONS *out,
490:     const fido_assert_ext_t *in)
491: {
492: 	WEBAUTHN_HMAC_SECRET_SALT_VALUES *v;
493: 	WEBAUTHN_HMAC_SECRET_SALT *s;
494: 
495: 	if (in->mask == 0) {
496: 		return 0; /* nothing to do */
497: 	}
498: 	if (in->mask != FIDO_EXT_HMAC_SECRET) {
499: 		fido_log_debug("%s: mask 0x%x", __func__, in->mask);
500: 		return -1;
501: 	}
502: 	if ((v = calloc(1, sizeof(*v))) == NULL ||
503: 	    (s = pack_hmac_salt(&in->hmac_salt)) == NULL) {
504: 		free(v);
505: 		fido_log_debug("%s: pack_hmac_salt", __func__);
506: 		return -1;
507: 	}
508: 	v->pGlobalHmacSalt = s;
509: 	out->pHmacSecretSaltValues = v;
510: 	out->dwFlags |= WEBAUTHN_AUTHENTICATOR_HMAC_SECRET_VALUES_FLAG;
511: 	out->dwVersion = WEBAUTHN_AUTHENTICATOR_GET_ASSERTION_OPTIONS_VERSION_6;
512: 
513: 	return 0;
