749: translate_fido_cred(struct winhello_cred *ctx, const fido_cred_t *cred,
750:     const char *pin, int ms)
751: {
752: 	WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS *opt;
753: 
754: 	if (pack_rp(&ctx->rp_id, &ctx->rp_name, &ctx->rp, &cred->rp) < 0) {
