758: 	if (pack_user(&ctx->user_name, &ctx->user_icon, &ctx->display_name,
759: 	    &ctx->user, &cred->user) < 0) {
760: 		fido_log_debug("%s: pack_user", __func__);
761: 		return FIDO_ERR_INTERNAL;
762: 	}
763: 	if (pack_cose(&ctx->alg, &ctx->cose, cred->type) < 0) {
764: 		fido_log_debug("%s: pack_cose", __func__);
765: 		return FIDO_ERR_INTERNAL;
766: 	}
767: 	if (pack_cd(&ctx->cd, &cred->cd) < 0) {
768: 		fido_log_debug("%s: pack_cd", __func__);
769: 		return FIDO_ERR_INTERNAL;
770: 	}
771: 	/* options */
772: 	opt = &ctx->opt;
773: 	opt->dwVersion = WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS_VERSION_1;
774: 	opt->dwTimeoutMilliseconds = ms < 0 ? MAXMSEC : (DWORD)ms;
775: 	opt->dwAttestationConveyancePreference =
776: 	    WEBAUTHN_ATTESTATION_CONVEYANCE_PREFERENCE_DIRECT;
777: 	if (pack_credlist(&opt->CredentialList, &cred->excl) < 0) {
778: 		fido_log_debug("%s: pack_credlist", __func__);
779: 		return FIDO_ERR_INTERNAL;
780: 	}
781: 	if (pack_cred_ext(opt, &cred->ext) < 0) {
782: 		fido_log_debug("%s: pack_cred_ext", __func__);
783: 		return FIDO_ERR_UNSUPPORTED_EXTENSION;
784: 	}
785: 	if (set_cred_uv(&opt->dwUserVerificationRequirement, (cred->ext.attr.mask &
786: 	    FIDO_EXT_CRED_PROTECT) ? FIDO_OPT_TRUE : cred->uv, pin) < 0) {
787: 		fido_log_debug("%s: set_cred_uv", __func__);
788: 		return FIDO_ERR_INTERNAL;
789: 	}
790: 	if (cred->rk == FIDO_OPT_TRUE) {
791: 		opt->bRequireResidentKey = true;
792: 	}
793: 	if (cred->ea.mode != 0) {
794: 		if (opt->dwVersion < WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS_VERSION_4) {
795: 			opt->dwVersion = WEBAUTHN_AUTHENTICATOR_MAKE_CREDENTIAL_OPTIONS_VERSION_4;
796: 		}
797: 		opt->dwEnterpriseAttestation = (DWORD)cred->ea.mode;
798: 	}
799: 
800: 	return FIDO_OK;
