135: 			return (-1);
136: 		}
137: 		if ((n = tx_frame(d, seq++, buf + sent, count - sent,
138: 		    ms)) == 0) {
139: 			fido_log_debug("%s: tx_frame", __func__);
140: 			return (-1);
141: 		}
142: 	}
