170: static int
171: nla_read(nlamsgbuf_t *a, void *buf, size_t cnt)
172: {
173: 	if (cnt > a->u.nla.nla_len ||
174: 	    fido_buf_read((void *)&a->ptr, &a->len, buf, cnt) < 0)
175: 		return (-1);
176: 
177: 	a->u.nla.nla_len = (uint16_t)(a->u.nla.nla_len - cnt);
178: 
179: 	return (0);
180: }
