207: static int
208: nlmsg_read(nlmsgbuf_t *m, void *buf, size_t cnt)
209: {
210: 	if (cnt > m->u.nlmsg.nlmsg_len ||
211: 	    fido_buf_read((void *)&m->ptr, &m->len, buf, cnt) < 0)
212: 		return (-1);
213: 
214: 	m->u.nlmsg.nlmsg_len = (uint32_t)(m->u.nlmsg.nlmsg_len - cnt);
215: 
216: 	return (0);
217: }
