220: nlmsg_write(nlmsgbuf_t *m, const void *buf, size_t cnt)
221: {
222: 	if (cnt > UINT32_MAX - m->u.nlmsg.nlmsg_len ||
223: 	    fido_buf_write(&m->ptr, &m->len, buf, cnt) < 0)
224: 		return (-1);
225: 
226: 	m->u.nlmsg.nlmsg_len = (uint32_t)(m->u.nlmsg.nlmsg_len + cnt);
227: 
228: 	return (0);
229: }
