324: nla_get_str(nlamsgbuf_t *a)
325: {
326: 	size_t n;
327: 	char *s = NULL;
328: 
329: 	if ((n = a->len) < 1 || a->ptr[n - 1] != '\0' ||
330: 	    (s = calloc(1, n)) == NULL || nla_read(a, s, n) < 0) {
331: 		free(s);
332: 		return (NULL);
333: 	}
334: 	s[n - 1] = '\0';
335: 
336: 	return (s);
