379: static int
380: nlmsg_iter(nlmsgbuf_t *m, void *arg, int (*parser)(nlamsgbuf_t *, void *))
381: {
382: 	nlamsgbuf_t *a;
383: 	int r;
384: 
385: 	while ((a = nlmsg_getattr(m)) != NULL) {
386: 		r = parser(a, arg);
387: 		free(a);
388: 		if (r < 0) {
389: 			fido_log_debug("%s: parser", __func__);
390: 			return (-1);
391: 		}
392: 	}
393: 
394: 	return (0);
395: }
