397: static int
398: nla_iter(nlamsgbuf_t *g, void *arg, int (*parser)(nlamsgbuf_t *, void *))
399: {
400: 	nlamsgbuf_t *a;
401: 	int r;
402: 
403: 	while ((a = nla_getattr(g)) != NULL) {
404: 		r = parser(a, arg);
405: 		free(a);
406: 		if (r < 0) {
407: 			fido_log_debug("%s: parser", __func__);
408: 			return (-1);
409: 		}
410: 	}
411: 
412: 	return (0);
413: }
