634: 	    nlmsg_set_u32(m, NFC_ATTR_DEVICE_INDEX, dev) < 0 ||
635: 	    nlmsg_tx(nl->fd, m) < 0) {
636: 		free(m);
637: 		return (-1);
638: 	}
639: 	free(m);
640: 	if ((r = nlmsg_rx(nl->fd, reply, sizeof(reply), ms)) < 0) {
641: 		fido_log_debug("%s: nlmsg_rx", __func__);
642: 		return (-1);
643: 	}
644: 	memset(&t, 0, sizeof(t));
