647: 	    NFC_CMD_GET_TARGET, &t, parse_target)) != 0) {
648: 		fido_log_debug("%s: nl_parse_reply: %d", __func__, ok);
649: 		return (-1);
650: 	}
651: 	if (!t.found) {
652: 		fido_log_debug("%s: target not found", __func__);
653: 		return (-1);
654: 	}
655: 
656: 	return (0);
