/* XXX avoid signed NLA_ALIGNTO */
#undef NLA_HDRLEN
#define NLA_HDRLEN	NLMSG_ALIGN(sizeof(struct nlattr))

typedef struct nlmsgbuf {
	size_t         siz; /* alloc size */
	size_t         len; /* of payload */
	unsigned char *ptr; /* in payload */
	union {
		struct nlmsghdr   nlmsg;
