} nlmsgbuf_t;

typedef struct genlmsgbuf {
	union {
		struct genlmsghdr genl;
		char              buf[GENL_HDRLEN];  /* align */
	}              u;
} genlmsgbuf_t;

typedef struct nlamsgbuf {
	size_t         siz; /* alloc size */
	size_t         len; /* of payload */
	unsigned char *ptr; /* in payload */
	union {
		struct nlattr     nla;
		char              buf[NLA_HDRLEN];   /* align */
	}              u;
